export function encodePairs(pairs) {
  // pairs: array of [key, value] strings; produces k1=v1&k2=v2
  return pairs.map(function (kv) { return kv[0] + "=" + kv[1]; }).join("&");
}

export function decodePairs(s) {
  if (s === "") return [];
  return s.split("&").map(function (part) {
    const i = part.indexOf("=");
    return [part.slice(0, i), part.slice(i + 1)];
  });
}

Keys and values containing =, &, or empty strings break the roundtrip in several distinct ways. npm install fast-check and write qs.test.mjs (node:test): property decodePairs(encodePairs(pairs)) deep-equals pairs for fc.array(fc.tuple(fc.string(), fc.string())). Run it, collect at least two structurally different shrunk counterexamples (an & inside a value; an = inside a key; also note what a key of "" does), record them as fixed regression cases with comments. Then fix by percent-encoding: encode each key and value with encodeURIComponent and decode with decodeURIComponent, and rerun the property at 1000 runs green. Add one more property: encodePairs output never contains a raw space and roundtrips through the fixed decoder even for unicode (fc.fullUnicodeString for values). All green via node --test.

